export interface ResumePageProps {
  html: string;
  pdfUrl: string;
}
function ProfileHeader() {
  return (
    <header className="profile-header">
      <a href="#resume">View resume</a>
      <h1>Professional profile</h1>
      <p>Experience, education, and selected work.</p>
    </header>
  );
}
function ResumeActions({ pdfUrl }: { pdfUrl: string }) {
  return (
    <nav aria-label="Resume actions">
      <a className="download-button" href={pdfUrl} download>
        Download PDF
      </a>
    </nav>
  );
}
export function ResumePage({ html, pdfUrl }: ResumePageProps) {
  return (
    <div className="profile-page">
      <ProfileHeader />
      <ResumeActions pdfUrl={pdfUrl} />
      <main id="resume" className="resume-panel">
        <div dangerouslySetInnerHTML={{ __html: html }} />
      </main>
      <footer>Thanks for taking a look.</footer>
    </div>
  );
}
